// The included crate encodes and checks its own record; its refusal keeps its word.
fn enc_oa_imported0(out: &mut ::std::vec::Vec<u8>, v: &OAImported0, depth: i32) {
    match abstraction_download_request_api::internal::encode_request_at(v, depth) {
        Ok(bytes) => out.extend_from_slice(&bytes),
        Err(e) => ::std::panic::panic_any(Refusal { word: e.word, offset: e.offset }),
    }
}

fn decode_oa_imported0(r: &mut Reader) -> ::std::result::Result<OAImported0, Refusal> {
    match abstraction_download_request_api::internal::decode_request_at(&r.buf[r.pos..], r.depth, r.limit) {
        Ok((v, n)) => {
            r.pos += n;
            Ok(v)
        }
        Err(e) => Err(Refusal { word: e.word, offset: r.pos + e.offset }),
    }
}

