fn named_encode_ref(v: &Ref, depth: i32) -> ::std::result::Result<::std::vec::Vec<u8>, Refusal> {
    match ::std::panic::catch_unwind(::std::panic::AssertUnwindSafe(|| {
        let mut out = ::std::vec::Vec::new();
        enc_ref(&mut out, v, depth);
        out
    })) {
        Ok(out) => Ok(out),
        Err(p) => match p.downcast::<Refusal>() {
            Ok(e) => Err(*e),
            Err(p) => ::std::panic::resume_unwind(p),
        },
    }
}

fn decode_ref_at(data: &[u8], depth: i32, limit: i32) -> ::std::result::Result<(Ref, usize), Refusal> {
    let mut r = Reader { buf: data, pos: 0, depth, limit: if limit < DEPTH_LIMIT { limit } else { DEPTH_LIMIT } };
    if depth < 0 || limit < 1 {
        return r.refuse("depth_exceeded");
    }
    r.skip_ws();
    let v = decode_ref(&mut r)?;
    Ok((v, r.pos))
}

